#!/usr/bin/env python3
"""Regenerate requirements.lock from the current interpreter."""
import importlib, platform
pkgs = ["numpy","pandas","scipy","statsmodels","matplotlib","h5py","pytest"]
lines = ["# Exact versions this analysis was last run and validated against.",
         "# Generated by scripts/record_environment.py — do not edit by hand.", "",
         f"# python {platform.python_version()}"]
for p in pkgs:
    try: lines.append(f"{p}=={importlib.import_module(p).__version__}")
    except Exception: lines.append(f"# {p} not installed")
open("requirements.lock", "w").write("\n".join(lines) + "\n")
print("wrote requirements.lock")
